/// Golden corpus for the offline NAM → CloData converter (metadata only).
///
/// A model becomes a GOLDEN reference only when the official Sonicake editor
/// produced both the model output (`HTCache\nam_output_wav.wav`) and the
/// CloData that was sent to the device (reconstructed from a USB capture).
/// Large artifacts stay in the external local capture directory; this file
/// only records where they are, their SHA-256 and their provenance. Nothing
/// here is generated by our own code.
library;

import 'dart:typed_data';

import 'nam_transfer_analysis.dart';
import 'usb_capture_reader.dart';

/// Validation state of a corpus case as recorded by the maintainer. The
/// authoritative result is always the comparison run against the local files.
enum MatriboxGoldenStatus { golden, needsOfficialOutput }

class MatriboxGoldenCase {
  const MatriboxGoldenCase({
    required this.id,
    required this.displayName,
    required this.storedName,
    required this.namSha256,
    required this.outputWav,
    required this.outputWavSha256,
    required this.clodataSha256,
    required this.provenance,
    this.officialClodata,
    this.capture,
    this.captureSha256,
    this.namLocalPath,
    this.referenceWav = 'v3/48000.wav',
    this.referenceWavSha256 =
        'a8da7250698124b564c3d526773dec40269f309d58e88af5ee43670ba4c3cf33',
  });

  final String id;
  final String displayName;

  /// File name handed to the converter (the editor derives the name field
  /// from it).
  final String storedName;
  final String namSha256;

  /// Paths relative to the external capture directory.
  final String referenceWav;
  final String referenceWavSha256;
  final String outputWav;
  final String outputWavSha256;

  /// Official CloData: either an already reconstructed file
  /// ([officialClodata]) or, preferred, the USBPcap [capture] it is
  /// reconstructed from with the V2 parser (source of truth).
  final String? officialClodata;
  final String? capture;
  final String? captureSha256;
  final String clodataSha256;

  /// Location of the imported `.nam` according to the editor log, if it
  /// still exists locally (SHA-256 is checked when present).
  final String? namLocalPath;
  final String provenance;
}

