/// Byte comparison of two CloData buffers.
class MatriboxCloDataDiff {
  MatriboxCloDataDiff(List<int> expected, List<int> actual)
    : expectedLength = expected.length,
      actualLength = actual.length {
    final common = expected.length < actual.length
        ? expected.length
        : actual.length;
    var run = -1;
    for (var i = 0; i < common; i++) {
      if (expected[i] == actual[i]) {
        matching++;
        run = -1;
        continue;
      }
      differing++;
      firstDifference ??= i;
      if (run >= 0 && regions.last.end == i) {
        regions.last = (start: regions.last.start, end: i + 1);
      } else {
        regions.add((start: i, end: i + 1));
      }
      run = i;
    }
  }

  final int expectedLength;
  final int actualLength;
  int matching = 0;
  int differing = 0;
  int? firstDifference;

  /// Contiguous differing regions, `[start, end)`.
  final List<({int start, int end})> regions = [];

  bool get identical =>
      expectedLength == actualLength && differing == 0 && matching > 0;

  @override
  String toString() =>
      'size $actualLength/$expectedLength, matching $matching, differing '
      '$differing in ${regions.length} region(s), first difference '
      '${firstDifference == null ? '-' : '0x${firstDifference!.toRadixString(16)}'}';
}

/// Reconstructs the official CloData from a USBPcap capture with the
/// validated V2 parser (independent of the converter).
Uint8List matriboxCloDataFromCapture(Uint8List pcapng) {
  final analysis = analyzeCloneTransfers({'X': readUsbCapture(pcapng)});
  final clo = analysis.artifacts['x_clodata.bin'];
  if (clo == null) {
    throw const FormatException('Capture does not contain a complete CloData.');
  }
  return clo;
}
